function escapeHtml(s) {
  if (s == null) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, -apple-system, sans-serif; max-width: 720px; margin: 2rem auto; padding: 0 1rem; color: #222; line-height: 1.5; }
  h1 { margin-top: 0; }
  h2 { margin-top: 2rem; border-bottom: 1px solid #eee; padding-bottom: 0.3rem; }
  a { color: #0066cc; }
  .book-list { list-style: none; padding: 0; margin: 0; }
  .book-list li { padding: 0.6rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  .book-list .meta { color: #666; font-size: 0.9rem; }
  label { display: block; margin: 0.8rem 0 0.3rem; font-weight: 600; }
  input[type="text"], textarea { width: 100%; padding: 0.5rem; border: 1px solid #ccc; border-radius: 4px; font-family: inherit; font-size: 1rem; box-sizing: border-box; }
  textarea { min-height: 8rem; resize: vertical; }
  .btn { display: inline-block; padding: 0.5rem 1rem; background: #0066cc; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 1rem; text-decoration: none; font-family: inherit; }
  .btn:hover { background: #0055aa; }
  .btn.secondary { background: #666; }
  .btn.secondary:hover { background: #555; }
  .actions { display: flex; gap: 0.5rem; margin-top: 1rem; align-items: center; }
  .actions form { margin: 0; }
  nav { margin-bottom: 1rem; }
  .empty { color: #888; font-style: italic; }
  .status-pill { display: inline-block; padding: 0.15rem 0.5rem; border-radius: 12px; font-size: 0.85rem; background: #eee; color: #555; }
  .status-pill.finished { background: #d4edda; color: #155724; }
  .error { color: #b00020; background: #fdecea; padding: 0.6rem 0.8rem; border-radius: 4px; }
  .meta-line { color: #666; font-size: 0.9rem; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function renderList(list, emptyMsg) {
  if (list.length === 0) {
    return `<p class="empty">${emptyMsg}</p>`;
  }
  const items = list
    .map(
      (b) => `    <li>
      <a href="/books/${encodeURIComponent(b.id)}">${escapeHtml(b.title)}</a>
      <span class="meta">${escapeHtml(b.author)}</span>
    </li>`
    )
    .join('\n');
  return `<ul class="book-list">\n${items}\n  </ul>`;
}

function renderHome(books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));

  return layout('My Books', `
  <h1>My Books</h1>
  <p><a class="btn" href="/add">+ Add a book</a></p>

  <h2>Currently reading (${reading.length})</h2>
  ${renderList(reading, 'Nothing in progress. <a href="/add">Add a book</a> to get started.')}

  <h2>Finished (${finished.length})</h2>
  ${renderList(finished, 'No finished books yet.')}
`);
}

function renderAddForm(values = {}, error = null) {
  const v = (key) => escapeHtml(values[key] ?? '');
  return layout('Add a book', `
  <nav><a href="/">&larr; Back to all books</a></nav>
  <h1>Add a book</h1>
  ${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
  <form method="POST" action="/add">
    <label for="title">Title</label>
    <input type="text" id="title" name="title" required value="${v('title')}" autofocus>

    <label for="author">Author</label>
    <input type="text" id="author" name="author" required value="${v('author')}">

    <div class="actions">
      <button type="submit" class="btn">Add book</button>
      <a href="/" class="btn secondary">Cancel</a>
    </div>
  </form>
`);
}

function renderBookDetail(book) {
  const statusClass = book.status === 'finished' ? 'status-pill finished' : 'status-pill';
  const finishedLine = book.finishedAt
    ? `<p class="meta-line">Finished on ${escapeHtml(new Date(book.finishedAt).toLocaleDateString())}</p>`
    : `<p class="meta-line">Added on ${escapeHtml(new Date(book.createdAt).toLocaleDateString())}</p>`;

  const statusBlock =
    book.status === 'reading'
      ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish">
        <button type="submit" class="btn">Mark as finished</button>
      </form>`
      : `<form method="POST" action="/books/${encodeURIComponent(book.id)}/unfinish">
        <button type="submit" class="btn secondary">Move back to currently reading</button>
      </form>`;

  const shareUrl = `/books/${encodeURIComponent(book.id)}`;

  return layout(book.title, `
  <nav><a href="/">&larr; All books</a></nav>
  <h1>${escapeHtml(book.title)}</h1>
  <p class="meta-line">by <strong>${escapeHtml(book.author)}</strong> &middot; <span class="${statusClass}">${escapeHtml(book.status)}</span></p>
  ${finishedLine}
  <p class="meta-line">Shareable link: <a href="${escapeHtml(shareUrl)}">${escapeHtml(shareUrl)}</a></p>

  <h2>Notes</h2>
  <form method="POST" action="/books/${encodeURIComponent(book.id)}/notes">
    <textarea name="notes" placeholder="Your thoughts, quotes, whatever...">${escapeHtml(book.notes ?? '')}</textarea>
    <div class="actions">
      <button type="submit" class="btn">Save notes</button>
    </div>
  </form>

  <h2>Status</h2>
  ${statusBlock}
`);
}

function renderNotFound() {
  return layout('Book not found', `
  <h1>Book not found</h1>
  <p><a href="/">Back to all books</a></p>
`);
}

export { escapeHtml, layout, renderHome, renderAddForm, renderBookDetail, renderNotFound };

