import { createServer } from 'node:http';
import { readBooks, writeBooks, generateId } from './storage.js';
import {
  renderHome,
  renderAddForm,
  renderBookDetail,
  renderNotFound,
  escapeHtml,
} from './views.js';

function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function redirect(res, location) {
  res.writeHead(302, { Location: location });
  res.end();
}

function send(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

const BOOK_PATH = /^\/books\/([^/]+)(?:\/(notes|finish|unfinish))?$/;

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
    const path = url.pathname;

    if (req.method === 'GET' && path === '/') {
      const books = await readBooks();
      return send(res, 200, renderHome(books));
    }

    if (req.method === 'GET' && path === '/add') {
      return send(res, 200, renderAddForm());
    }

    if (req.method === 'POST' && path === '/add') {
      const body = await parseBody(req);
      const params = new URLSearchParams(body);
      const title = (params.get('title') ?? '').trim();
      const author = (params.get('author') ?? '').trim();

      if (!title || !author) {
        return send(
          res,
          400,
          renderAddForm({ title, author }, 'Both title and author are required.')
        );
      }

      const books = await readBooks();
      const book = {
        id: generateId(),
        title,
        author,
        notes: '',
        status: 'reading',
        createdAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
